use App\Config\Constants\UsersConstants as UC;
use App\Config\Constants\CompaniesConstants as CC;

Schema::create('departments', function (Blueprint $table) {
    $table->uuid('id')->primary();
    $table->string('name');

    // Multiple FKs — loop
    $fkColumns = [
        UC::COL_USER_ID    => UC::TABLE,
        CC::COL_COMPANY_ID => CC::TABLE,
    ];
    foreach ($fkColumns as $col => $refTable) {
        $table->foreignUuid($col)
              ->nullable()
              ->constrained($refTable)
              ->nullOnDelete();
    }

    $table->timestamps();
    $table->softDeletes();
});

public function down(): void
{
    Schema::table(DC::TABLE_DOCUMENTS, function (Blueprint $table) {
        $fkColumns = [UC::COL_CREATED_BY, CC::COL_COMPANY_ID];
        foreach ($fkColumns as $col) {
            $table->dropForeign([$col]);
            $table->dropColumn($col);
        }
    });
}
